func tInit(p *planctx.Plan, maxRounds int32, fetchLimit int32) int32 {
	// A fresh plan with the two limits set, as a host sets them from its Config.
	p.MaxRounds = maxRounds
	p.FetchLimit = fetchLimit
	return 0
}

func tNthId(c *port.Cells, k int32) int32 {
	// The id of the k-th record of `c`.
	var at int32 = 0
	var i int32 = 0
	for i < k {
		at += port.CellsAt(c, at)
		i += 1
	}
	return port.CellsAt(c, at+2)
}

func tNthKind(c *port.Cells, k int32) int32 {
	var at int32 = 0
	var i int32 = 0
	for i < k {
		at += port.CellsAt(c, at)
		i += 1
	}
	return port.CellsAt(c, at+1)
}

func tNthStatus(c *port.Cells, k int32) int32 {
	var at int32 = 0
	var i int32 = 0
	for i < k {
		at += port.CellsAt(c, at)
		i += 1
	}
	return plan.AnStatus(c, at)
}

func tTxReqId(tx *port.Cells, at int32) int32 {
	var r int32 = planloop.TxReq(tx, at)
	return port.CellsAt(tx, r+2)
}

func tTxAnsId(tx *port.Cells, at int32) int32 {
	var a int32 = planloop.TxAns(tx, at)
	return port.CellsAt(tx, a+2)
}

func tTxAnsStatus(tx *port.Cells, at int32) int32 {
	var a int32 = planloop.TxAns(tx, at)
	return plan.AnStatus(tx, a)
}

func tRender(p *planctx.Plan, id int32) int32 {
	plan.RqRender(p.Rq, id, 0, id, 144, 0)
	return 0
}

func tOcr(p *planctx.Plan, id int32) int32 {
	var at int32 = plan.RqOcr(p.Rq, id, 1, 6, 0, 0, 0, 0, 0)
	plan.RqOcrEnd(p.Rq, at)
	return 0
}

func tAnswer(p *planctx.Plan, id int32) int32 {
	// Offer a render answer to request `id`.
	port.CellsDrop(p.Cur, 0)
	plan.AnRender(p.Cur, id, 10, 20, 3, 144)
	return planloop.PlOffer(p)
}

func tErr(emonT *testing.T, p *planctx.Plan, code int32, name string, msg string) int32 {
	// The error the machine holds: its name by `pe`, and its sentence.
	var t *strings.Builder = port.NewText()
	port.AssertEq(emonT, p.Err, code, name)
	port.AssertEq(emonT, planloop.PeEmitName(t, p.Err), 1, name)
	port.AssertText(emonT, p.Msg, msg, name)
	return 0
}

