	port.AssertEq(emonT, tTxReqId(p.Tx, nxt), 5, "then the render of 5")
	port.AssertEq(emonT, tTxAnsStatus(p.Tx, nxt), plan.PsOk(), "ok")
	port.AssertEq(emonT, planloop.TxNext(p.Tx, nxt), port.CellsLen(p.Tx), "and that is all")
