func TestAFinishedUnitIsFoldedIntoTheTotals(emonT *testing.T) {
	var p *planctx.Plan = planctx.NewPlan()
	tInit(p, 5, 24)
	planloop.PlAttempt(p)
	planloop.PlAfter(p, plan.UsNeedBytes())
	planloop.PlAttempt(p)
	tRender(p, 1)
	tRender(p, 2)
	planloop.PlAfter(p, plan.UsRequests())
	p.BytesRequests = 4
	planloop.PlFold(p)
	port.AssertEq(emonT, p.TAttempts, 2, "attempts")
	port.AssertEq(emonT, p.TFetchRounds, 1, "fetch rounds")
	port.AssertEq(emonT, p.TBytesRequests, 4, "bytes requests")
	port.AssertEq(emonT, p.TRequests, 2, "requests")
	port.AssertEq(emonT, p.Attempts, 0, "the unit is reset")
	port.AssertEq(emonT, port.CellsLen(p.Ans), 0, "its answers are gone")
	planloop.EnNext(p, 1, 1, 0, 2)
	planloop.PlAttempt(p)
	tRender(p, 3)
	planloop.PlAfter(p, plan.UsRequests())
	planloop.PlFold(p)
	port.AssertEq(emonT, p.TAttempts, 3, "the asset unit counts its attempts too")
	port.AssertEq(emonT, p.TRequests, 3, "and its requests")
	planloop.EnNext(p, 1, 1, 0, 2)
	planloop.PlAttempt(p)
	tRender(p, 4)
	tRender(p, 5)
	planloop.PlAfter(p, plan.UsRequests())
	planloop.PlFold(p)
	port.AssertEq(emonT, p.TAttempts, 3, "a page unit does not count its attempts")
	port.AssertEq(emonT, p.TRequests, 5, "but its requests")
	port.AssertEq(emonT, port.CellsLen(p.Pgq), 1, "it keeps the requests it made")
	port.AssertEq(emonT, port.CellsAt(p.Pgq, 0), 2, "two")
	port.AssertEq(emonT, port.CellsAt(p.Pgr, 0), 1, "in one round")
}

func TestThePortsARequestGoesTo(emonT *testing.T) {
	port.AssertEq(emonT, planloop.PlRoute(plan.PkDecode(), 0), planloop.RtDecode(), "decode: the host's codecs")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkDecodeImg(), 0), planloop.RtDecodeImg(), "decode-img: the host's codecs")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkOcr(), 0), planloop.RtUnsupported(), "ocr with no engine")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkOcr(), planloop.PpOcr()), planloop.RtOcr(), "ocr with one")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkOcr(), planloop.PpRender()), planloop.RtUnsupported(), "a renderer is not an engine")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkRender(), 0), planloop.RtUnsupported(), "render with no renderer")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkCrop(), 0), planloop.RtUnsupported(), "crop with no renderer")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkRender(), planloop.PpRender()), planloop.RtRender(), "render with one")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkCrop(), planloop.PpRender()+planloop.PpOcr()), planloop.RtRender(), "crop with both")
	port.AssertEq(emonT, planloop.PlRoute(plan.PkBytes(), 3), planloop.RtNone(), "bytes is the loop's own")
	port.AssertEq(emonT, planloop.PlRoute(77, 3), planloop.RtNone(), "no such kind")
}

