func TestTheSpansOfAnInputARequestNames(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var o *port.Cells = port.NewCells()
	plan.RqDecode(c, 1, 0, 100, 50, 0, 0)
	plan.RqDecode(c, 2, 3, 100, 50, 0, 0)
	plan.RqDecode(c, 3, 0, -1, 50, 0, 0)
	plan.RqDecode(c, 4, 0, 100, 0, 0, 0)
	plan.RqRender(c, 5, 0, 0, 144, 0)
	port.AssertEq(emonT, planloop.PlSpans(c, 0, 0, o), 1, "a decode of this input")
	port.AssertEq(emonT, port.CellsAt(o, 0), 100, "its offset")
	port.AssertEq(emonT, port.CellsAt(o, 1), 50, "its length")
	port.AssertEq(emonT, planloop.PlSpans(c, 8, 0, o), 0, "a decode of another input")
	port.AssertEq(emonT, planloop.PlSpans(c, 16, 0, o), 0, "a decode at a negative offset")
	port.AssertEq(emonT, planloop.PlSpans(c, 24, 0, o), 0, "a decode of no bytes")
	port.AssertEq(emonT, planloop.PlSpans(c, 32, 0, o), 0, "a render names no bytes")
	port.AssertEq(emonT, port.CellsLen(o), 2, "nothing else was written")
}

func tZeros(c *port.Cells, n int32) int32 {
	// Append n zeros: the words of two SHA-256s, or a residency map with nothing resident.
	var i int32 = 0
	for i < n {
		port.CellsPush(c, 0)
		i += 1
	}
	return 0
}

