func tPlanFetch(pend *port.Cells, hint *port.Cells, res *port.Cells, chunk int32, total int32, round int32, out *port.Cells) int32 {
	return planloop.FpPlan(pend, hint, res, chunk, total, 7, round, out)
}

func tRange(emonT *testing.T, out *port.Cells, k int32, off int32, ln int32, msg string) int32 {
	// Range k of the plan is `off` and `ln` long, of input 7.
	port.AssertEq(emonT, port.CellsAt(out, k*3), 7, msg)
	port.AssertEq(emonT, port.CellsAt(out, (k*3)+1), off, msg)
	port.AssertEq(emonT, port.CellsAt(out, (k*3)+2), ln, msg)
	return 0
}

